class Solution:
    def minCostSetTime(self, startAt, moveCost, pushCost, targetSeconds):
        def cost(mins, secs):
            if mins < 0 or mins > 99 or secs < 0 or secs > 99:
                return float('inf')
            s = str(mins * 100 + secs)
            cur = str(startAt)
            res = 0
            for c in s:
                if c != cur:
                    res += moveCost
                    cur = c
                res += pushCost
            return res
        ans = float('inf')
        for m in range(100):
            s = targetSeconds - m * 60
            if 0 <= s <= 99:
                ans = min(ans, cost(m, s))
        return ans

class Solution:
    def smallestNumber(self, num):
        if num == 0: return 0
        neg = num < 0
        digits = sorted(str(abs(num)))
        if neg:
            return -int(''.join(digits[::-1]))
        else:
            for i, d in enumerate(digits):
