class Solution:
    def maximumANDSum(self, nums, numSlots):
        @lru_cache(maxsize=None)
        def dp(i, mask):
            if i == len(nums): return 0
            res = 0
            for slot in range(1, numSlots + 1):
                b = (mask // (3 ** (slot-1))) % 3
                if b < 2:
                    new_mask = mask + 3 ** (slot-1)
                    res = max(res, (nums[i] & slot) + dp(i+1, new_mask))
            return res
        return dp(0, 0)

