class Solution:
    def countPairs(self, nums, k):
        gcds = Counter()
        for num in nums:
            gcds[gcd(num, k)] += 1
        ans = 0
        keys = list(gcds.keys())
        for i in range(len(keys)):
            for j in range(i, len(keys)):
