class Solution:
    def buildWall(self, height, width, bricks):
        patterns = []
        def gen(pos, splits):
            if pos == width:
                patterns.append(frozenset(splits))
                return
            for b in bricks:
                if pos + b <= width:
                    if pos + b < width:
                        gen(pos + b, splits | {pos + b})
                    else:
                        gen(pos + b, splits)
        gen(0, set())
        n = len(patterns)
        compat = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if not patterns[i] & patterns[j]:
                    compat[i].append(j)
        MOD = 10**9 + 7
        dp = [1] * n
        for _ in range(height - 1):
            ndp = [0] * n
            for i in range(n):
                for j in compat[i]:
                    ndp[j] = (ndp[j] + dp[i]) % MOD
            dp = ndp
        return sum(dp) % MOD

