class Solution:
    def minimumFinishTime(self, tires, changeTime, numLaps):
        # best[j] = min time to run j consecutive laps without changing
        MAX_NO_CHANGE = 18  # f*r^j grows exponentially
        best = [float('inf')] * (MAX_NO_CHANGE + 1)
        for f, r in tires:
            total = 0
            cur = f
            for j in range(1, MAX_NO_CHANGE + 1):
                total += cur
                best[j] = min(best[j], total)
                cur *= r
                if cur > 2 * 10**5:
                    break
        dp = [float('inf')] * (numLaps + 1)
        dp[0] = -changeTime
        for i in range(1, numLaps + 1):
            for j in range(1, min(i, MAX_NO_CHANGE) + 1):
                dp[i] = min(dp[i], dp[i-j] + changeTime + best[j])
        return dp[numLaps]

