class Solution:
    def getAncestors(self, n, edges):
        from collections import defaultdict
        children = defaultdict(list)
        for u, v in edges:
            children[u].append(v)
        ans = [set() for _ in range(n)]
        def dfs(start, node):
            for child in children[node]:
                if start not in ans[child]:
                    ans[child].add(start)
                    dfs(start, child)
        for i in range(n):
            dfs(i, i)
        return [sorted(s) for s in ans]

class Solution:
    def minMovesToMakePalindrome(self, s):
        s = list(s)
        ans = 0
        while len(s) > 1:
            # find match for s[0] from the right
            i = len(s) - 1
            while s[i] != s[0]:
                i -= 1
            if i == 0:
                # odd char, move to middle
                ans += len(s) // 2
                s.pop(0)
            else:
                ans += len(s) - 1 - i
                s.pop(i)
                s.pop(0)
        return ans

