class Solution:
    def singleDivisorTriplet(self, nums):
        cnt = Counter(nums)
        vals = sorted(cnt.keys())
        ans = 0
        for i, a in enumerate(vals):
            for j in range(i, len(vals)):
                b = vals[j]
                for k in range(j, len(vals)):
                    c = vals[k]
                    s = a + b + c
                    divs = (s % a == 0) + (s % b == 0) + (s % c == 0)
                    if divs != 1: continue
                    if a == b == c:
                        ways = cnt[a] * (cnt[a]-1) * (cnt[a]-2)
                    elif a == b:
                        ways = cnt[a] * (cnt[a]-1) * cnt[c]
                    elif b == c:
                        ways = cnt[a] * cnt[b] * (cnt[b]-1)
                    elif a == c:
                        ways = cnt[a] * (cnt[a]-1) * cnt[b]
                    else:
                        ways = cnt[a] * cnt[b] * cnt[c]
                    ans += ways * 3 if a == b == c else ways * (3 if len(set([a,b,c])) == 3 else 3)
        return ans

