class Solution:
    def maximumSubsequenceCount(self, text, pattern):
        a, b = pattern[0], pattern[1]
        cnt_b = 0
        base = 0
        for c in text:
            if c == b:
                cnt_b += 1
            if c == a:
                base += cnt_b
        # add a at beginning: adds total count of b in text
        # add b at end: adds total count of a in text
        cnt_a = text.count(a)
        cnt_b_total = text.count(b)
        return base + max(cnt_b_total, cnt_a)

class Solution:
    def minimumWhiteTiles(self, floor, numCarpets, carpetLen):
        n = len(floor)
        # dp[i][j] = min white tiles in floor[0..i-1] using j carpets
        dp = [[0] * (numCarpets + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(numCarpets + 1):
                # don't place carpet ending at i
                dp[i][j] = dp[i-1][j] + (1 if floor[i-1] == '1' else 0)
                # place carpet ending at i
                if j > 0:
                    prev = max(0, i - carpetLen)
                    dp[i][j] = min(dp[i][j], dp[prev][j-1])
        return dp[n][numCarpets]

