class Solution:
    def minDeletion(self, nums):
        deletions = 0
        i = 0
        n = len(nums)
        while i < n - 1:
            # current effective index is i - deletions
            if (i - deletions) % 2 == 0 and nums[i] == nums[i+1]:
                deletions += 1
            i += 1
        # ensure even length
        if (n - deletions) % 2 == 1:
            deletions += 1
        return deletions

class Solution:
    def kthPalindrome(self, queries, intLength):
        half_len = (intLength + 1) // 2
        start = 10 ** (half_len - 1)
        end = 10 ** half_len - 1
        res = []
        for q in queries:
            num = start + q - 1
            if num > end:
                res.append(-1)
            else:
                s = str(num)
                if intLength % 2 == 0:
