        return res

class Solution:
    def maxValueOfCoins(self, piles, k):
        dp = [0] * (k + 1)
        for pile in piles:
            # prefix sums for this pile
            prefix = [0]
            for coin in pile:
                prefix.append(prefix[-1] + coin)
                if len(prefix) > k + 1:
                    break
            ndp = dp[:]
            for j in range(1, min(len(prefix), k + 1)):
                for prev in range(k - j + 1):
                    ndp[prev + j] = max(ndp[prev + j], dp[prev] + prefix[j])
            dp = ndp
        return dp[k]

class Solution:
    def maximumSumScore(self, nums):
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]
        ans = float('-inf')
        for i in range(n):
            left_sum = prefix[i+1]
            right_sum = prefix[n] - prefix[i]
            ans = max(ans, left_sum, right_sum)
        return ans

